#include "tigersheets/ooxml.hpp"
#include <pugixml.hpp>
#include <filesystem>
#include <iostream>
#include <stdexcept>
#include <unistd.h>
using namespace tigersheets;
void require(bool value,const char* message){if(!value)throw std::runtime_error(message);}
int main(){try{
 char temporary[]="/tmp/tigersheets-structural-style-XXXXXX";const auto* directory=mkdtemp(temporary);require(directory,"temporary fixture directory");const std::string path=(std::filesystem::path(directory)/"row-style.xlsx").string();
 auto book=WorkbookSession().snapshot();book["sheets"][0]["cells"]=Json::array({{{"row",1},{"col",1},{"input","1"},{"style",{{"bold",true}}}},{{"row",2},{"col",1},{"input","2"}}});writeWorkbook(path,book);auto source=readWorkbook(path);auto moved=source.workbook;auto& cells=moved["sheets"][0]["cells"];cells.erase(cells.begin());cells[0]["row"]=1;moved["sheets"][0]["structuralRevision"]=1;writeWorkbook(path,moved,&source);const auto result=readWorkbook(path);const auto& cell=result.workbook.at("sheets")[0].at("cells")[0];require(cell.at("input")=="2","row deletion moves remaining value");require(!cell.contains("style")||!cell.at("style").value("bold",false),"moving an unformatted cell does not inherit overwritten native formatting");const auto resetPath=(std::filesystem::path(directory)/"reset-style.xlsx").string();auto styled=WorkbookSession().snapshot();styled["sheets"][0]["cells"]=Json::array({{{"row",1},{"col",1},{"input","Revenue"},{"style",{{"fill","#FFCC88"},{"color","#AA0011"},{"alignment","center"},{"wrap",true},{"bold",true}}}}});writeWorkbook(resetPath,styled);auto imported=readWorkbook(resetPath);auto reset=imported.workbook;auto& resetStyle=reset["sheets"][0]["cells"][0]["style"];resetStyle["fill"]="";resetStyle["color"]="";resetStyle["alignment"]="";writeWorkbook(resetPath,reset,&imported);const auto reopened=readWorkbook(resetPath);pugi::xml_document nativeStyles,sheetXml;require(nativeStyles.load_string(reopened.entries.at("xl/styles.xml").c_str())&&sheetXml.load_string(reopened.entries.at("xl/worksheets/sheet1.xml").c_str()),"reset style XML readable");const int styleIndex=sheetXml.child("worksheet").child("sheetData").child("row").child("c").attribute("s").as_int();auto xf=nativeStyles.child("styleSheet").child("cellXfs").first_child();for(int i=0;i<styleIndex;++i)xf=xf.next_sibling();require(xf.attribute("fillId").as_int()==0,"No Fill clears the imported native fill instead of authoring an empty RGB");auto font=nativeStyles.child("styleSheet").child("fonts").first_child();for(int i=0;i<xf.attribute("fontId").as_int();++i)font=font.next_sibling();require(font.child("color").attribute("auto").as_bool()&&!font.child("color").attribute("rgb"),"Automatic font color overrides inherited RGB with native auto color");require(std::string(xf.child("alignment").attribute("horizontal").value())=="general"&&xf.child("alignment").attribute("wrapText").as_bool()&&font.child("b"),"General alignment reset preserves independent wrap and bold settings");std::filesystem::remove_all(directory);std::cout<<"Worksheet structural style tests passed\n";return 0;
 }catch(const std::exception& error){std::cerr<<error.what()<<'\n';return 1;}}
